cat > main.ts <<'EOF'
const text = await Deno.readTextFile(Deno.args[0]);
const tok = text.split(/\s+/).filter((s) => s.length > 0).map(Number);
const width = tok[0], height = tok[1], steps = tok[2];
const n = width * height;
const init = new Uint32Array(n);
for (let i = 0; i < n; i++) init[i] = tok[3 + i] ?? 0;

const shader = `
struct P { w: u32, h: u32 };
@group(0) @binding(0) var<storage, read> src: array<u32>;
@group(0) @binding(1) var<storage, read_write> dst: array<u32>;
@group(0) @binding(2) var<uniform> p: P;
@compute @workgroup_size(64)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
  let i = gid.x;
  if (i >= p.w * p.h) { return; }
  let x = i % p.w;
  let y = i / p.w;
  let l = select(x - 1u, 0u, x == 0u);
  let r = select(x + 1u, p.w - 1u, x + 1u >= p.w);
  let u = select(y - 1u, 0u, y == 0u);
  let d = select(y + 1u, p.h - 1u, y + 1u >= p.h);
  let s = 4u * src[i] + src[y * p.w + l] + src[y * p.w + r] + src[u * p.w + x] + src[d * p.w + x];
  dst[i] = s / 8u;
}`;

let result = init;
if (steps > 0) {
  const adapter = await navigator.gpu.requestAdapter();
  if (!adapter) throw new Error("no GPU adapter");
  const device = await adapter.requestDevice();
  const bytes = n * 4;
  const U = GPUBufferUsage;
  const bufs = [0, 1].map(() =>
    device.createBuffer({ size: bytes, usage: U.STORAGE | U.COPY_SRC | U.COPY_DST })
  );
  device.queue.writeBuffer(bufs[0], 0, init);
  const uni = device.createBuffer({ size: 16, usage: U.UNIFORM | U.COPY_DST });
  device.queue.writeBuffer(uni, 0, new Uint32Array([width, height, 0, 0]));
  const module = device.createShaderModule({ code: shader });
  const pipeline = device.createComputePipeline({
    layout: "auto",
    compute: { module, entryPoint: "main" },
  });
  const groups = [0, 1].map((k) =>
    device.createBindGroup({
      layout: pipeline.getBindGroupLayout(0),
      entries: [
        { binding: 0, resource: { buffer: bufs[k] } },
        { binding: 1, resource: { buffer: bufs[1 - k] } },
        { binding: 2, resource: { buffer: uni } },
      ],
    })
  );
  const enc = device.createCommandEncoder();
  const wg = Math.ceil(n / 64);
  for (let s = 0; s < steps; s++) {
    const pass = enc.beginComputePass();
    pass.setPipeline(pipeline);
    pass.setBindGroup(0, groups[s % 2]);
    pass.dispatchWorkgroups(wg);
    pass.end();
  }
  const out = bufs[steps % 2];
  const read = device.createBuffer({ size: bytes, usage: U.MAP_READ | U.COPY_DST });
  enc.copyBufferToBuffer(out, 0, read, 0, bytes);
  device.queue.submit([enc.finish()]);
  await read.mapAsync(GPUMapMode.READ);
  result = new Uint32Array(read.getMappedRange().slice(0));
  read.unmap();
}

const lines: string[] = [];
let sum = 0;
for (let y = 0; y < height; y++) {
  const row: number[] = [];
  for (let x = 0; x < width; x++) {
    const v = result[y * width + x];
    sum += v;
    row.push(v);
  }
  lines.push(row.join(" "));
}
lines.push(`SUM ${sum}`);
await Deno.stdout.write(new TextEncoder().encode(lines.join("\n") + "\n"));
Deno.exit(0);
EOF
printf '3 2 2\n8 16 24\n0 800 1000000\n' > /tmp/in.txt
deno check main.ts && deno run --allow-read main.ts /tmp/in.txt

